'use strict';
let practicePDFURL='';
function practiceOptions(){return {ink:$('practiceInk').checked,lyrics:$('practiceLyrics').checked,diagrams:$('practiceDiagrams').checked,pattern:$('practicePattern').checked,checklist:$('practiceChecklist').checked,note:$('practiceNote').value.trim().slice(0,600),goal:$('practiceGoal').value.trim().slice(0,200)};}
function practiceSheetHTML(s,o){
 const cfg=METERS[s.meter],names=songChords(s),beats=i=>s.meter==='6/8'?String(i+1):`${Math.floor(i/2)+1}${i%2?' &':''}`;
 const shapes=o.diagrams?`<h2>Find your chords</h2><div class="practice-shapes">${names.map(c=>`<div><b>${esc(c)}</b>${diagram(c)}</div>`).join('')}</div>`:'';
 const pattern=o.pattern?`<h2>Your strumming pattern</h2><p>${esc(STRUM_PATTERNS[s.pattern].name)}</p><div class="practice-pattern">${STRUM_PATTERNS[s.pattern].pattern.map((p,i)=>`<span><b>${{D:'↓',U:'↑',X:'×','.':'·'}[p.type]}</b><small>${s.meter==='6/8'?String(i+1):i%2?'&':String(Math.floor(i/2)+1)}</small></span>`).join('')}</div><p class="practice-cue">↓ Down &nbsp; ↑ Up &nbsp; × Mute &nbsp; · Keep your hand moving</p>`:'';
 // The editor supplies phrase-level lyric timing. Keep the exact beat labels;
 // do not invent a word-by-word alignment that the song data does not contain.
 const groups=[];for(let i=0;i<s.measures.length;i+=4){const bars=s.measures.slice(i,i+4);const words=[];
  if(o.lyrics)for(let k=0;k<s.measures.length;k++){const m=s.measures[k];if(m.ending||!m.lyric.trim())continue;const start=k*cfg.steps+m.lyricStart,end=Math.min(s.measures.length*cfg.steps,start+m.lyricSpan*cfg.steps);if(start<(i+bars.length)*cfg.steps&&end>i*cfg.steps){const pickup=normalizePickup(m.lyricPickup,normalizePickup(s.lyricPickup)),label=k<i?'Continued':`Measure ${k+1} · ${s.meter==='6/8'?'count':'beat'} ${beats(m.lyricStart)}`;words.push(`<p class="practice-lyric">${esc(m.lyric)}</p><p class="practice-cue">${label}${pickup?` · begin ${pickup===.5?'½':pickup} beat${pickup===1?'':'s'} early`:''}</p>`);}}
  const cells=bars.map((m,k)=>`<div class="phrase-bar"><small>${m.ending?'Final strum':`Measure ${i+k+1}`}${m.sectionStart?' · '+esc(m.sectionStart):''}</small><div class="bar-changes">${m.chords.map(c=>`<span><strong>${esc(c.chord==='--'?'Rest':c.chord)}</strong><small>${s.meter==='6/8'?'Count':'Beat'} ${beats(c.step)}</small></span>`).join('')}</div></div>`).join('');groups.push(`<section class="practice-phrase"><div class="phrase-bars">${cells}</div>${words.join('')}</section>`);
 }
 const routine=o.checklist?'<h2>My practice week</h2><p class="practice-routine">1 minute: Find your chord shapes.<br>2 minutes: Practice the chord changes slowly.<br>2 minutes: Strum the song'+(o.lyrics&&s.measures.some(m=>m.lyric.trim())?' and sing the words.':'.')+'</p><div class="practice-days">'+['Mon','Tue','Wed','Thu','Fri'].map(d=>`<span>${d}<i></i></span>`).join('')+'</div>':'';
 return `<article class="practice-sheet"><p class="practice-byline">MR. DREW’S UKE STRUM · TAKE-HOME PRACTICE</p><h1>${esc(s.title)}</h1>${s.video?.composer?`<p>Composed by ${esc(s.video.composer)}</p>`:''}<div class="practice-name"><span>Name: __________________________</span><span>Date: ______________</span></div><p class="practice-meta">${s.meter} time · Practice tempo: ${s.tempo}${s.meter==='6/8'?' dotted-quarter':''} BPM · G–C–E–A tuning</p>${shapes}${pattern}<h2>${o.lyrics?'Strum and sing your song':'Follow the chord changes'}</h2><p class="practice-cue">One box = one measure. Change chords on the beat shown.</p>${groups.join('')}${o.goal?`<h2>My goal</h2><p class="practice-note">${esc(o.goal)}</p>`:''}${o.note?`<h2>Teacher’s note</h2><p class="practice-note">${esc(o.note)}</p>`:''}${routine}<footer>Created with Mr. Drew’s Uke Strum · Drew Wichman</footer></article>`;
}
function openPracticeSheet(){if(isViewer||isProjector)return;if(exerciseBackup)leaveExercise();if(transport.state==='playing')pause();if($('optionsModal').open)$('optionsModal').close();$('practiceSongName').textContent=song.title;$('practiceLyrics').checked=song.measures.some(m=>!m.ending&&m.lyric.trim());$('practicePdfPreview').hidden=true;$('practicePdfLinks').hidden=true;$('practicePdfStatus').textContent='';$('practiceModal').classList.remove('has-pdf-preview');$('practiceModal').showModal();}
function initPracticeSheet(){
 document.body.insertAdjacentHTML('beforeend',`<dialog id="practiceModal" class="modal practice-dialog" aria-labelledby="practiceHeading"><div class="modal-header"><div><div class="eyebrow">TAKE THE MUSIC HOME</div><h2 id="practiceHeading">Student practice sheet</h2></div><button id="practiceClose" aria-label="Close practice sheet options">✕</button></div><div class="practice-fields"><p id="practiceSongName"></p><div class="row"><label class="check"><input id="practiceLyrics" type="checkbox" checked>Lyrics</label><label class="check"><input id="practiceDiagrams" type="checkbox" checked>Chord diagrams</label></div><div class="row"><label class="check"><input id="practicePattern" type="checkbox" checked>Strumming pattern</label><label class="check"><input id="practiceChecklist" type="checkbox" checked>Practice checklist</label></div><label class="check"><input id="practiceInk" type="checkbox">Ink-saver edition · grayscale</label><label>Practice goal · optional<input id="practiceGoal" maxlength="200" placeholder="Keep a steady beat while changing chords."></label><label>Teacher’s note · optional<textarea id="practiceNote" maxlength="600" placeholder="Try it slowly, then sing as you strum."></textarea></label><p class="hint">Includes every chord change with its exact beat. Lyrics sit beneath their matching chord measures, with pickup and entry cues when needed. A designed, print-ready PDF keeps its layout on every computer.</p><div class="row practice-pdf-actions"><button id="practicePreview" class="primary">Preview PDF</button><button id="practicePrint">Download PDF</button></div><p id="practicePdfStatus" class="hint" role="status"></p><div id="practicePdfLinks" class="row" hidden><a id="practicePdfDownload" download>Download practice sheet</a><a id="practicePdfOpen" target="_blank" rel="noopener">Open / print PDF ↗</a></div><iframe id="practicePdfPreview" title="Preview of the student practice sheet" hidden></iframe></div></dialog>`);
 $('openPracticeSheet').onclick=openPracticeSheet;$('printBtn').onclick=openPracticeSheet;$('practiceClose').onclick=()=>$('practiceModal').close();
 $('practicePrint').onclick=()=>createPracticePDF(false);$('practicePreview').onclick=()=>createPracticePDF(true);
}

async function createPracticePDF(preview=true){
 const buttons=[$('practicePrint'),$('practicePreview')];buttons.forEach(b=>b.disabled=true);$('practicePdfStatus').textContent='Designing your practice sheet…';
 try{
  const bytes=await UkePracticePDF.build(clone(song),practiceOptions(),{fingerings:CHORD_FINGERINGS,fingers:FINGERS,meters:METERS,pattern:STRUM_PATTERNS[song.pattern]});
  const previous=practicePDFURL;practicePDFURL=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));
  const link=$('practicePdfDownload');link.href=practicePDFURL;link.download=(song.title.replace(/[^\p{L}\p{N}_ -]/gu,'').trim().slice(0,90)||'My_song')+'_Practice.pdf';$('practicePdfOpen').href=practicePDFURL;$('practicePdfLinks').hidden=false;
  $('practicePdfStatus').textContent='Your practice sheet is ready. Open the PDF to print it, or download a copy.';
  if(preview||!$('practicePdfPreview').hidden)$('practicePdfPreview').src=practicePDFURL+'#toolbar=0&navpanes=0';
  if(preview){$('practicePdfPreview').hidden=false;$('practiceModal').classList.add('has-pdf-preview');}else link.click();
  if(previous)setTimeout(()=>URL.revokeObjectURL(previous),1000);
 }catch(e){$('practicePdfStatus').textContent='Could not create the PDF: '+(e.message||'Please try again.');}
 finally{buttons.forEach(b=>b.disabled=false);}
}
